      {q:"बच्चन के काव्य में 'हालावाद' का क्या तात्पर्य है?", ans:"हालावाद में मधु, मदिरा, हाला और प्याला प्रतीक हैं जिनके माध्यम से कवि जीवन के आनंद, विषाद और दर्शन को अभिव्यक्त करता है। यह जीवन को समग्रता में स्वीकारने का दर्शन है।", type:"short"},
      {q:"'आत्मपरिचय' कविता की भाषा-शैली पर टिप्पणी कीजिए।", ans:"कविता की भाषा सरल, प्रवाहमयी और भावप्रवण है। आत्मकथ्यात्मक शैली में कवि ने अपने अंतर्मन का सच्चा चित्रण किया है, जिसमें ओज और आत्मविश्वास की झलक मिलती है।", type:"short"},
      {q:"'मधुशाला' बच्चन की प्रसिद्धि का आधार क्यों है?", ans:"'मधुशाला' में हाला, प्याला और मधुशाला के प्रतीकों से जीवन-दर्शन की अभिव्यक्ति हुई है। इसकी गेयता और दार्शनिक गहराई ने इसे जन-जन की कृति बनाया।", type:"short"},
      {q:"'आत्मपरिचय' में निहित जीवन-दर्शन स्पष्ट कीजिए।", ans:"कवि का जीवन-दर्शन है कि जीवन के दुःख और संघर्ष से पलायन करने के बजाय उन्हें स्वीकार कर आगे बढ़ना चाहिए। यही संघर्षशील आशावाद कविता की आत्मा है।", type:"short"},
      {q:"बच्चन को छायावादोत्तर कवि क्यों कहा जाता है?", ans:"बच्चन की कविता में छायावादी वायवीयता के बजाय जीवन की ठोस अनुभूतियों और व्यक्तिगत संघर्ष की अभिव्यक्ति है। उनका स्वर आत्मपरक और यथार्थोन्मुख है, इसलिए वे छायावादोत्तर कवि माने जाते हैं।", type:"short"},
      {q:"'आत्मपरिचय' शीर्षक की सार्थकता स्पष्ट कीजिए।", ans:"कविता में कवि ने अपने व्यक्तित्व, जीवन-दृष्टि और संघर्ष का सच्चा परिचय दिया है। शीर्षक कविता की आत्मकथ्यात्मक प्रकृति के पूर्णतः अनुरूप है।", type:"short"},
      {q:"बच्चन की कविता में आत्मकथ्य की विशेषता लिखिए।", ans:"बच्चन की कविता में आत्मकथ्य ईमानदार और निश्छल है; वे अपने सुख-दुःख, आशा-निराशा को बिना आवरण के प्रस्तुत करते हैं। यही सच्चाई उनके काव्य को मार्मिक बनाती है।", type:"short"},
      {q:"'आत्मपरिचय' में कवि ने जीवन के भार को कैसे स्वीकारा है?", ans:"कवि 'जग-जीवन का भार' लिए फिरने की बात कहकर जीवन की जिम्मेदारियों को सहर्ष स्वीकार करता है। वह भार से दबने के बजाय उसे शक्ति में बदलने का संदेश देता है।", type:"short"},
      {q:"हरिवंश राय बच्चन का साहित्यिक परिचय दीजिए।", ans:"हरिवंश राय बच्चन (1907–2003) हिंदी के प्रसिद्ध कवि हैं; 'मधुशाला', 'मधुबाला' और 'मधुकलश' उनकी प्रमुख कृतियाँ हैं। उन्हें 1976 में पद्मभूषण से सम्मानित किया गया।", type:"short"},
      {q:"'पतंग' कविता में बाल-मनोविज्ञान का चित्रण स्पष्ट कीजिए।", ans:"कवि ने पतंग उड़ाते बच्चों की आतुरता, उल्लास और कल्पना-शक्ति का सूक्ष्म चित्रण किया है। बच्चों के मन पतंग के साथ ही आकाश की ऊँचाइयों को छूते हैं, जो बाल-मन की निश्छलता को प्रकट करता है।", type:"short"},
      {q:"'पतंग' कविता में निहित प्रतीकात्मकता स्पष्ट कीजिए।", ans:"पतंग स्वतंत्रता, उल्लास और कल्पना-शक्ति का प्रतीक है; डोर जीवन के संबंधों और आकाश असीम संभावनाओं का प्रतीक है। कवि ने सामान्य दृश्य को गहन अर्थ से जोड़ दिया है।", type:"short"},
      {q:"आलोक धन्वा का साहित्यिक परिचय दीजिए।", ans:"आलोक धन्वा (जन्म 1948, मुंगेर, बिहार) समकालीन हिंदी कविता के सशक्त कवि हैं। 'पतंग' उनकी प्रसिद्ध कविता है जिसमें बाल-सुलभ उमंग का सजीव चित्रण है।", type:"short"},
      {q:"'पतंग' कविता की बिंब-योजना पर टिप्पणी कीजिए।", ans:"कविता में छतों पर दौड़ते बच्चे, डोर खींचने की आतुरता और आकाश में लहराती पतंग जैसे सजीव बिंब हैं। ये बिंब पाठक के मन में उल्लास का चित्र उकेर देते हैं।", type:"short"},
      {q:"'पतंग' में कवि ने स्वतंत्रता की अभिलाषा कैसे व्यक्त की है?", ans:"पतंग के आकाश में ऊँचे उड़ने और बच्चों के मन के उसी के साथ उड़ने के चित्रण से कवि ने स्वतंत्रता की सहज मानवीय अभिलाषा व्यक्त की है। यह अभिलाषा बाल-मन में सबसे निश्छल रूप में दिखती है।", type:"short"},
      {q:"'पतंग' कविता का शिल्पगत वैशिष्ट्य लिखिए।", ans:"कविता मुक्त छंद में रची गई है; भाषा सरल और चित्रात्मक है। छोटे-छोटे बिंबों से कवि ने दृश्य को जीवंत कर दिया है, जो समकालीन कविता की विशेषता है।", type:"short"},
      {q:"कविता में बच्चों के उल्लास के कारण लिखिए।", ans:"पतंग के आकाश में लहराने, डोर के तनाव और साथियों के साथ प्रतिस्पर्धा से बच्चों में उल्लास उमड़ता है। यह उल्लास उनकी कल्पना-शक्ति और जीवन के प्रति सहज आकर्षण का परिणाम है।", type:"short"},
      {q:"'पतंग' शीर्षक की सार्थकता स्पष्ट कीजिए।", ans:"पतंग कविता का केंद्रीय बिंब और प्रतीक है; उसी के इर्द-गिर्द बाल-उल्लास, स्वतंत्रता और कल्पना के भाव बुने गए हैं। अतः शीर्षक पूर्णतः सार्थक है।", type:"short"},
      {q:"'पतंग' कविता में कवि की दृष्टि की विशेषता बताइए।", ans:"कवि की दृष्टि सूक्ष्म और संवेदनशील है; वह सामान्य से दिखने वाले दृश्य में भी गहन मानवीय भाव देख लेता है। बाल-मन के प्रति उसकी आत्मीयता कविता में झलकती है।", type:"short"},
      {q:"'पतंग' और 'कविता के बहाने' में भाव-साम्य लिखिए।", ans:"दोनों कविताएँ जीवन की सहज अनुभूतियों से जुड़ी हैं; 'पतंग' में बाल-उल्लास और 'कविता के बहाने' में मानवीय संवेदना केंद्रीय है। दोनों में कविता को जीवन से जोड़ने का भाव है।", type:"short"},
      {q:"'कविता के बहाने' शीर्षक की सार्थकता स्पष्ट कीजिए।", ans:"कवि ने कविता के बहाने कविता के स्वरूप, उद्देश्य और जीवन से उसके संबंध पर विचार किया है। शीर्षक कविता की चिंतनपरक प्रकृति को सटीक रूप से व्यक्त करता है।", type:"short"},
      {q:"कुँवर नारायण का साहित्यिक परिचय दीजिए।", ans:"कुँवर नारायण (1927–2017) 'तीसरा सप्तक' के प्रमुख कवि हैं; उन्हें 2005 में ज्ञानपीठ पुरस्कार मिला। उनकी कविता में चिंतन और संवेदना का सुंदर समन्वय है।", type:"short"},
      {q:"कवि के अनुसार कविता और जीवन का संबंध स्पष्ट कीजिए।", ans:"कुँवर नारायण के अनुसार सच्ची कविता जीवन की गहरी अनुभूतियों से उपजती है और मनुष्य को व्यापक मानवीय सत्य से जोड़ती है। कविता जीवन से कटी नहीं हो सकती।", type:"short"},
      {q:"'कविता के बहाने' में कवि ने शाब्दिक चमत्कार का विरोध क्यों किया है?", ans:"कवि मानता है कि केवल शब्दों का खेल कविता नहीं है; सच्ची कविता में मानवीय संवेदना और जीवन-सत्य का होना आवश्यक है। शाब्दिक चमत्कार कविता की आत्मा नहीं हो सकता।", type:"short"},
      {q:"कुँवर नारायण की काव्य-दृष्टि की विशेषता लिखिए।", ans:"कुँवर नारायण की काव्य-दृष्टि चिंतनप्रधान और मानवीय है; वे सामान्य विषयों में भी गहन दार्शनिक अर्थ खोज लेते हैं। उनकी भाषा संयमित और बिंब सटीक होते हैं।", type:"short"},
      {q:"'कैमरे में बंद अपाहिज' में मीडिया की संवेदनहीनता कैसे उजागर हुई है?", ans:"कार्यक्रम बनाने वाले अपाहिज की पीड़ा को सनसनी बनाकर TRP बटोरना चाहते हैं; उससे बार-बार उसकी अपंगता के बारे में पूछा जाता है। यह मानवीय पीड़ा का तमाशा बनाना मीडिया की क्रूर संवेदनहीनता है।", type:"short"},
      {q:"रघुवीर सहाय का साहित्यिक परिचय दीजिए।", ans:"रघुवीर सहाय (1929–1990) प्रमुख कवि और 'दिनमान' साप्ताहिक के संपादक थे। 'लोग भूल गए हैं' पर उन्हें साहित्य अकादमी पुरस्कार मिला; उनकी कविता में तीखा सामाजिक व्यंग्य है।", type:"short"},
      {q:"'कैमरे में बंद अपाहिज' शीर्षक की सार्थकता स्पष्ट कीजिए।", ans:"अपाहिज व्यक्ति कैमरे की नज़र में कैद है; उसकी पीड़ा को कार्यक्रम के लिए सीमित करके परोसा जाता है। शीर्षक मीडिया के शोषणकारी रवैये को उजागर करता है।", type:"short"},
      {q:"कविता में 'अपाहिज' के प्रति कार्यक्रम-निर्माताओं का व्यवहार स्पष्ट कीजिए।", ans:"निर्माता अपाहिज को दया का पात्र नहीं, बल्कि सनसनी का साधन मानते हैं। वे उसकी पीड़ा को कुरेदकर दर्शकों का मनोरंजन करना चाहते हैं, जो अमानवीय है।", type:"short"},
      {q:"रघुवीर सहाय की व्यंग्य-दृष्टि की विशेषता लिखिए।", ans:"रघुवीर सहाय का व्यंग्य तीखा और यथार्थपरक है; वे सत्ता, मीडिया और मध्यवर्गीय पाखंड पर सीधा प्रहार करते हैं। उनका व्यंग्य करुणा से भी जुड़ा होता है।", type:"short"},
      {q:"कविता में कैमरे की भूमिका स्पष्ट कीजिए।", ans:"कैमरा मीडिया की निर्मम नज़र का प्रतीक है जो मानवीय पीड़ा को भी 'शॉट' में बदल देता है। वह सत्य को नहीं, बिकाऊ सनसनी को कैद करता है।", type:"short"},
      {q:"'कैमरे में बंद अपाहिज' का सामाजिक संदेश लिखिए।", ans:"कविता का संदेश है कि मीडिया को मानवीय पीड़ा का तमाशा नहीं बनाना चाहिए; विकलांग व्यक्तियों के प्रति संवेदना और सम्मान का भाव रखना आवश्यक है।", type:"short"},
      {q:"कविता की भाषा-शैली पर टिप्पणी कीजिए।", ans:"कविता की भाषा सरल, बोलचाल की और व्यंग्य से भरी है। संवादात्मक शैली में कवि ने टेलीविजन कार्यक्रम की कृत्रिमता को बेनकाब किया है।", type:"short"},
      {q:"कार्यक्रम-निर्माताओं के प्रश्नों का अपाहिज पर क्या प्रभाव पड़ता है?", ans:"बार-बार पीड़ा के बारे में पूछे जाने से अपाहिज मानसिक रूप से आहत होता है; उसकी निजता भंग होती है। यह प्रश्न उसे व्यक्ति नहीं, 'मामला' बना देते हैं।", type:"short"},
      {q:"रघुवीर सहाय को 'सजग पत्रकार-कवि' क्यों कहा जाता है?", ans:"रघुवीर सहाय ने 'दिनमान' के संपादक के रूप में पत्रकारिता और कविता दोनों में सामाजिक सजगता दिखाई। उनकी रचनाओं में समकालीन यथार्थ की तीखी पहचान मिलती है।", type:"short"},
      {q:"'उषा' कविता में भोर के सौंदर्य का चित्रण स्पष्ट कीजिए।", ans:"कवि ने भोर के नभ को 'नीले शंख' जैसे बिंब से चित्रित किया है; उषा का आगमन नायिका के समान सजीव है। प्रकृति के सूक्ष्म सौंदर्य का यह चित्रण अत्यंत मोहक है।", type:"short"},
      {q:"शमशेर बहादुर सिंह का साहित्यिक परिचय दीजिए।", ans:"शमशेर बहादुर सिंह (1911–1993) 'दूसरा सप्तक' के प्रमुख कवि हैं। उनकी कविता में बिंबात्मकता, सूक्ष्मता और प्रकृति के प्रति तादात्म्य की विशेषता है।", type:"short"},
      {q:"'उषा' में मानवीकरण अलंकार का प्रयोग स्पष्ट कीजिए।", ans:"कवि ने उषा को नायिका के रूप में चित्रित किया है; भोर का आगमन किसी सुंदरी के पदार्पण जैसा लगता है। यह मानवीकरण कविता को सजीवता प्रदान करता है।", type:"short"},
      {q:"'प्रात नभ था बहुत नीला शंख जैसे' पंक्ति का भावार्थ लिखिए।", ans:"कवि कहता है कि भोर का आकाश अत्यंत नीला था, जैसे कोई नीला शंख हो। इस बिंब से भोर की पवित्रता, शांति और सौंदर्य एक साथ व्यक्त हुए हैं।", type:"short"},
      {q:"शमशेर की काव्य-भाषा की विशेषता लिखिए।", ans:"शमशेर की भाषा बिंबप्रधान और सूक्ष्म है; वे कम शब्दों में गहन अर्थ भर देते हैं। उनकी भाषा में चित्रात्मकता और संगीतात्मकता का सुंदर मेल है।", type:"short"},
      {q:"'उषा' कविता में कवि का प्रकृति-प्रेम कैसे व्यक्त हुआ है?", ans:"कवि भोर के प्रत्येक परिवर्तन को मुग्ध दृष्टि से देखता है और प्रकृति के साथ तादात्म्य स्थापित करता है। उसका प्रकृति-प्रेम दार्शनिक गहराई से युक्त है।", type:"short"},
      {q:"'उषा' कविता का मूल भाव लिखिए।", ans:"कविता का मूल भाव प्रकृति के सौंदर्य के प्रति मुग्धता और उसके साथ आत्मीय तादात्म्य है। भोर का सौंदर्य कवि के मन में शांति और पवित्रता का संचार करता है।", type:"short"},
      {q:"शमशेर को 'कवियों का कवि' क्यों कहा जाता है?", ans:"शमशेर की बिंब-योजना, भाषायी सूक्ष्मता और शिल्प-सजगता से कवि-समुदाय विशेष प्रभावित रहा है। उनकी कला-चेतना ने अनेक कवियों को प्रेरित किया, इसलिए वे 'कवियों के कवि' कहलाते हैं।", type:"short"},
      {q:"'उषा' और 'बादल राग' में प्रकृति-चित्रण का अंतर स्पष्ट कीजिए।", ans:"'उषा' में प्रकृति सौंदर्य और शांति का प्रतीक है, जबकि 'बादल राग' में बादल क्रांति का प्रतीक है। एक में प्रकृति के प्रति मुग्धता है, दूसरे में क्रांतिकारी आह्वान।", type:"short"},
      {q:"'उषा' कविता की बिंब-योजना पर टिप्पणी कीजिए।", ans:"कविता में नीले शंख जैसे सटीक और मौलिक बिंब हैं; प्रत्येक बिंब भोर के सौंदर्य का नया पक्ष उजागर करता है। बिंबों की सूक्ष्मता शमशेर की पहचान है।", type:"short"},
      {q:"'बादल राग' में कवि ने बादलों का आह्वान क्यों किया है?", ans:"कवि बादलों से समाज में व्याप्त शोषण और विषमता को मिटाने का आह्वान करता है। बादल क्रांति के प्रतीक हैं जो जर्जर व्यवस्था को ध्वस्त कर नवीन समाज की रचना करेंगे।", type:"short"},
      {q:"निराला का साहित्यिक परिचय दीजिए।", ans:"सूर्यकांत त्रिपाठी 'निराला' छायावाद के महाप्राण कवि हैं; 'अनामिका', 'गीतिका' और 'तुलसीदास' उनकी प्रमुख कृतियाँ हैं। उनकी कविता में ओज, विद्रोह और करुणा का समन्वय है।", type:"short"},
      {q:"'विप्लव के वीर' संबोधन का तात्पर्य स्पष्ट कीजिए।", ans:"'विप्लव' का अर्थ क्रांति है; कवि बादलों को क्रांति के वीर कहकर उन्हें सामाजिक परिवर्तन का दूत बनाता है। यह संबोधन कविता के क्रांतिकारी स्वर को प्रकट करता है।", type:"short"},
      {q:"'बादल राग' में बादल के द्विविध रूप स्पष्ट कीजिए।", ans:"बादल शोषकों के लिए विनाशकारी और शोषितों के लिए आशा का दूत है; उसकी गर्जना में क्रांतिकारी उद्घोष है तो वर्षा में नवजीवन का संदेश। यही उसका द्विविध रूप है।", type:"short"},
      {q:"निराला की 'बादल राग' में निहित सामाजिक चेतना लिखिए।", ans:"कविता में दलित-शोषित वर्ग के प्रति गहरी सहानुभूति और शोषणकारी व्यवस्था के प्रति तीव्र आक्रोश है। कवि क्रांति द्वारा समतामूलक समाज की स्थापना का स्वप्न देखता है।", type:"short"},
      {q:"'बादल राग' कविता की भाषा-शैली पर टिप्पणी कीजिए।", ans:"कविता की भाषा तत्समप्रधान, ओजस्वी और गर्जनापूर्ण है। लंबे-लंबे समासों और ध्वन्यात्मक शब्दों से बादल की प्रचंडता सजीव हो उठी है।", type:"short"},
      {q:"'बादल राग' में क्रांति और करुणा का समन्वय स्पष्ट कीजिए।", ans:"कवि एक ओर शोषकों के विनाश का आह्वान करता है, दूसरी ओर शोषितों के प्रति करुणा व्यक्त करता है। क्रांति का उद्देश्य ही करुणामय समाज की स्थापना है।", type:"short"},
      {q:"निराला को 'महाप्राण' क्यों कहा जाता है?", ans:"निराला की कविता में उदात्त भावना, प्रचंड ओज और मानवीय करुणा का विराट समन्वय है। उनके व्यक्तित्व और काव्य की महत्ता के कारण वे 'महाप्राण' कहलाते हैं।", type:"short"},
      {q:"'बादल राग' का शीर्षक सार्थक है — स्पष्ट कीजिए।", ans:"'राग' का अर्थ अनुराग और लय है; कविता में बादल के प्रति कवि का क्रांतिकारी अनुराग लयबद्ध हुआ है। शीर्षक कविता के भाव और संगीत दोनों को व्यक्त करता है।", type:"short"},
      {q:"'बादल राग' में चित्रित बादल और सामान्य वर्षा-बादल में अंतर लिखिए।", ans:"सामान्य बादल केवल वर्षा करता है, जबकि 'बादल राग' का बादल क्रांति का दूत है। वह सामाजिक विषमता को मिटाने का संकल्प लिए हुए है।", type:"short"},
      {q:"'लक्ष्मण-मूर्छा' प्रसंग में राम के विलाप का वर्णन कीजिए।", ans:"लक्ष्मण के मूर्छित होने पर राम शोक-विह्वल होकर विलाप करते हैं; वे लक्ष्मण के बिना जीवन को निरर्थक बताते हैं। इस विलाप में भ्रातृ-प्रेम की पराकाष्ठा व्यक्त हुई है।", type:"short"},
      {q:"तुलसीदास का साहित्यिक परिचय दीजिए।", ans:"गोस्वामी तुलसीदास (1532–1623) भक्तिकाल के महान कवि हैं; 'रामचरितमानस', 'विनयपत्रिका' और 'कवितावली' उनकी प्रमुख कृतियाँ हैं। उनकी भक्ति में दास्य भाव प्रमुख है।", type:"short"},
      {q:"'कवितावली' की भाषागत विशेषता लिखिए।", ans:"'कवितावली' ब्रजभाषा में रचित है; इसमें कवित्त, सवैया और छप्पय छंदों का प्रयोग हुआ है। भाषा में ओज, माधुर्य और भक्तिभाव का सुंदर समन्वय है।", type:"short"},
      {q:"'लक्ष्मण-मूर्छा' में भ्रातृ-प्रेम की अभिव्यक्ति स्पष्ट कीजिए।", ans:"राम का विलाप बताता है कि लक्ष्मण उनके लिए प्राणों से भी प्रिय हैं; वे कहते हैं कि लक्ष्मण के बिना अयोध्या लौटना व्यर्थ है। यह प्रसंग आदर्श भ्रातृ-प्रेम का उदाहरण है।", type:"short"},
      {q:"तुलसीदास की भक्ति में 'दास्य भाव' का तात्पर्य स्पष्ट कीजिए।", ans:"दास्य भाव में भक्त स्वयं को प्रभु का सेवक मानता है; तुलसीदास राम के चरणों के दास बनकर भक्ति करते हैं। यही भाव उनकी रचनाओं की आत्मा है।", type:"short"},
      {q:"'कवितावली' के उत्तरकांड का महत्त्व लिखिए।", ans:"उत्तरकांड में तुलसीदास ने कलियुग की सामाजिक दुर्दशा, अन्याय और कष्टों का यथार्थ चित्रण किया है। यह उनके समय का जीवंत सामाजिक दस्तावेज़ है।", type:"short"},
      {q:"राम के विलाप में निहित मानवीय संवेदना स्पष्ट कीजिए।", ans:"मर्यादा पुरुषोत्तम राम का विलाप दिखाता है कि ईश्वरत्व के बावजूद उनमें मानवीय संवेदना है। भाई के प्रति उनका शोक मानवीय प्रेम की गहराई को प्रकट करता है।", type:"short"},
      {q:"'कवितावली' और 'रामचरितमानस' में भाषा का अंतर लिखिए।", ans:"'कवितावली' ब्रजभाषा में और 'रामचरितमानस' अवधी में रचित है। दोनों में तुलसी की भक्ति-भावना समान है, परंतु भाषायी माधुर्य में भिन्नता है।", type:"short"},
      {q:"तुलसीदास के काव्य में लोकमंगल की भावना स्पष्ट कीजिए।", ans:"तुलसीदास का काव्य लोक-कल्याण के लिए है; वे रामकथा के माध्यम से आदर्श जीवन-मूल्यों की स्थापना करते हैं। उनका साहित्य जन-जन का मार्गदर्शन करता है।", type:"short"},
      {q:"'लक्ष्मण-मूर्छा' प्रसंग की नाटकीयता पर टिप्पणी कीजिए।", ans:"प्रसंग में युद्ध की भयावहता, लक्ष्मण की मूर्छा और राम के विलाप का सजीव चित्रण है; पाठक के मन में करुणा और उत्सुकता एक साथ जगती है। यह नाटकीयता तुलसी की कला का प्रमाण है।", type:"short"},
      {q:"फ़िराक़ गोरखपुरी का साहित्यिक परिचय दीजिए।", ans:"फ़िराक़ गोरखपुरी (रघुपति सहाय, 1896–1982) उर्दू के प्रसिद्ध शायर हैं; 'गुले नग्मा' पर उन्हें 1969 में ज्ञानपीठ पुरस्कार मिला। उनकी रुबाइयों में प्रेम और जीवन-दर्शन की अभिव्यक्ति है।", type:"short"},
      {q:"'रुबाई' छंद की विशेषता लिखिए।", ans:"रुबाई चार मिसरों वाली छंद-रचना है जिसमें प्रथम, द्वितीय और चतुर्थ मिसरे में तुक होता है। इसमें एक पूर्ण भाव संक्षेप में व्यक्त होता है।", type:"short"},
      {q:"फ़िराक़ की रुबाइयों का मूल भाव स्पष्ट कीजिए।", ans:"फ़िराक़ की रुबाइयों में प्रेम, सौंदर्य और जीवन के प्रति गहन अनुभूति है। वे जीवन के सुख-दुःख को दार्शनिक दृष्टि से देखते हैं।", type:"short"},
      {q:"गज़ल के 'मतला' और 'मकता' का तात्पर्य लिखिए।", ans:"गज़ल का प्रथम शेर 'मतला' कहलाता है जिसमें दोनों मिसरों में तुक होता है; अंतिम शेर 'मकता' कहलाता है जिसमें शायर अपना उपनाम रखता है।", type:"short"},
      {q:"फ़िराक़ की भाषा-शैली की विशेषता लिखिए।", ans:"फ़िराक़ की भाषा सरल, भावप्रवण और संगीतमय है; उर्दू-फारसी के शब्दों का प्रयोग सहज है। उनकी शैली में शास्त्रीयता और आधुनिकता का मेल है।", type:"short"},
      {q:"रुबाइयों में निहित जीवन-दर्शन स्पष्ट कीजिए।", ans:"फ़िराक़ की रुबाइयों में जीवन को प्रेम और सौंदर्य से जीने का संदेश है; वे क्षणभंगुर जीवन में भी आनंद खोजने की प्रेरणा देते हैं।", type:"short"},
      {q:"गज़ल और रुबाई में अंतर स्पष्ट कीजिए।", ans:"गज़ल में कम से कम पाँच शेर होते हैं और प्रत्येक शेर स्वतंत्र भाव व्यक्त करता है; रुबाई चार मिसरों की एकल भाव-रचना है। दोनों उर्दू काव्य की प्रमुख विधाएँ हैं।", type:"short"},
      {q:"फ़िराक़ को ज्ञानपीठ पुरस्कार क्यों मिला?", ans:"फ़िराक़ को उर्दू काव्य-संग्रह 'गुले नग्मा' पर 1969 में ज्ञानपीठ पुरस्कार मिला। यह उर्दू साहित्य के लिए प्रथम ज्ञानपीठ था, जो उनकी साहित्यिक महत्ता को दर्शाता है।", type:"short"},
      {q:"फ़िराक़ की रुबाइयों में प्रेम-भावना का स्वरूप लिखिए।", ans:"फ़िराक़ का प्रेम उदात्त और आध्यात्मिक है; वह केवल वैयक्तिक नहीं, बल्कि सार्वभौमिक मानवीय भावना है। उनके प्रेम में विरह और मिलन दोनों की गहराई है।", type:"short"},
      {q:"'रुबाइयाँ' शीर्षक की सार्थकता स्पष्ट कीजिए।", ans:"संग्रह में फ़िराक़ की प्रसिद्ध रुबाइयाँ संकलित हैं; प्रत्येक रुबाई में जीवन का कोई न कोई सत्य झलकता है। शीर्षक संग्रह की विधा और विषय दोनों को स्पष्ट करता है।", type:"short"},
      {q:"'भक्तिन' पाठ में सेविका के प्रति लेखिका का भाव स्पष्ट कीजिए।", ans:"महादेवी वर्मा भक्तिन को केवल सेविका नहीं, बल्कि परिवार का सदस्य मानती हैं; उसके प्रति उनमें गहन स्नेह और सम्मान है। यह भाव मानवीय समता का प्रतीक है।", type:"short"},
      {q:"महादेवी वर्मा का साहित्यिक परिचय दीजिए।", ans:"महादेवी वर्मा (1907–1987) छायावाद की प्रमुख कवयित्री हैं; 'यामा' पर उन्हें 1982 में ज्ञानपीठ पुरस्कार मिला। उन्हें 'आधुनिक मीरा' कहा जाता है।", type:"short"},
      {q:"भक्तिन के चरित्र की प्रमुख विशेषताएँ लिखिए।", ans:"भक्तिन सरल, निष्ठावान और मुँहफट स्वभाव की थी; लेखिका के प्रति उसकी निष्ठा अटूट थी। उसकी सेवा में स्वार्थ नहीं, सच्चा स्नेह था।", type:"short"},
      {q:"'भक्तिन' रेखाचित्र की विशेषता स्पष्ट कीजिए।", ans:"यह संस्मरणात्मक रेखाचित्र है जिसमें एक सामान्य सेविका का जीवंत चरित्र-चित्रण हुआ है। लेखिका ने छोटे-छोटे प्रसंगों से भक्तिन के व्यक्तित्व को उकेरा है।", type:"short"},
      {q:"भक्तिन का नाम 'लछमिन' से 'भक्तिन' कैसे पड़ा?", ans:"उसका वास्तविक नाम लछमिन था, परंतु लेखिका के प्रति उसकी अटूट भक्ति और सेवा-भाव देखकर महादेवी ने उसे 'भक्तिन' नाम दिया। यह नाम उसके चरित्र का सच्चा परिचायक है।", type:"short"},
      {q:"'भक्तिन' पाठ में निहित मानवीय संदेश लिखिए।", ans:"पाठ का संदेश है कि सेवक और स्वामी में भी मानवीय स्नेह और समता का संबंध हो सकता है। सच्ची सेवा में निष्ठा और प्रेम होता है, दासता नहीं।", type:"short"},
      {q:"महादेवी वर्मा की गद्य-शैली की विशेषता लिखिए।", ans:"महादेवी की गद्य-शैली भावप्रवण, चित्रात्मक और संस्कृतनिष्ठ है। वे सामान्य पात्रों में भी असामान्य मानवीय गरिमा खोज लेती हैं।", type:"short"},
      {q:"भक्तिन और लेखिका के संबंध की विशेषता बताइए।", ans:"दोनों के बीच स्वामी-सेवक से बढ़कर आत्मीय संबंध था; भक्तिन लेखिका की सुख-दुःख की साथी थी। यह संबंध मानवीय संवेदना का आदर्श उदाहरण है।", type:"short"},
      {q:"'भक्तिन' पाठ का शीर्षक सार्थक है — स्पष्ट कीजिए।", ans:"भक्तिन का संपूर्ण जीवन लेखिका के प्रति भक्ति और सेवा में समर्पित था; शीर्षक उसके चरित्र की मूल विशेषता को व्यक्त करता है। अतः शीर्षक पूर्णतः सार्थक है।", type:"short"},
      {q:"महादेवी वर्मा को 'आधुनिक मीरा' क्यों कहा जाता है?", ans:"महादेवी के काव्य में मीरा जैसी वेदना, समर्पण और आध्यात्मिक प्रेम की अभिव्यक्ति है। उनकी भक्तिभावना और करुण स्वर के कारण वे 'आधुनिक मीरा' कहलाती हैं।", type:"short"},
      {q:"बाज़ार जाने से पहले मनुष्य को क्या विचार करना चाहिए? (पाठ के आधार पर)", ans:"पाठ के अनुसार बाज़ार जाने से पहले मनुष्य को अपनी वास्तविक आवश्यकता का विचार करना चाहिए। बिना आवश्यकता के बाज़ार जाना प्रलोभन में फँसना है।", type:"short"},
      {q:"जैनेंद्र कुमार का साहित्यिक परिचय दीजिए।", ans:"जैनेंद्र कुमार (1905–1988) प्रसिद्ध कथाकार और निबंधकार हैं; 'त्यागपत्र' और 'सुनीता' उनकी प्रमुख कृतियाँ हैं। वे गाँधीवादी विचारधारा से प्रभावित थे।", type:"short"},
      {q:"लेखक के अनुसार बाज़ार का आकर्षण मनुष्य को कैसे फँसाता है?", ans:"बाज़ार कृत्रिम आवश्यकताएँ जगाकर मनुष्य को अनावश्यक वस्तुएँ खरीदने के लिए प्रेरित करता है। इस आकर्षण में फँसकर व्यक्ति आर्थिक और मानसिक दासता में जकड़ जाता है।", type:"short"},
      {q:"'बाज़ार दर्शन' शीर्षक की सार्थकता स्पष्ट कीजिए।", ans:"लेखक ने बाज़ार का केवल वर्णन नहीं, बल्कि उसके स्वरूप का गहन दर्शन (चिंतन) प्रस्तुत किया है। शीर्षक पाठ की चिंतनपरक प्रकृति के अनुरूप है।", type:"short"},
      {q:"जैनेंद्र कुमार की निबंध-कला की विशेषता लिखिए।", ans:"जैनेंद्र के निबंधों में दार्शनिक चिंतन और मनोवैज्ञानिक विश्लेषण है; भाषा सरल परंतु अर्थगर्भित है। वे सामान्य विषयों में भी गहन जीवन-सत्य खोज लेते हैं।", type:"short"},
      {q:"पाठ में 'संयम' का क्या महत्त्व बताया गया है?", ans:"लेखक के अनुसार संयम से मनुष्य बाज़ार के प्रलोभनों से बचता है और सच्चे सुख को प्राप्त करता है। संयम ही उपभोक्तावादी संस्कृति का प्रतिकार है।", type:"short"},
      {q:"लेखक बाज़ार को किस दृष्टि से देखता है?", ans:"लेखक बाज़ार को उपभोक्तावादी संस्कृति के प्रतीक के रूप में देखता है जो मनुष्य की कमजोरियों का लाभ उठाता है। उसकी दृष्टि आलोचनात्मक परंतु सुधारवादी है।", type:"short"},
      {q:"'बाज़ार दर्शन' में गाँधीवादी विचारधारा कैसे झलकती है?", ans:"अपरिग्रह, संयम और आवश्यकता-आधारित जीवन के संदेश में गाँधीवादी विचारधारा झलकती है। लेखक सादगीपूर्ण जीवन का समर्थन करता है।", type:"short"},
      {q:"उपभोक्तावादी संस्कृति के दुष्परिणाम लिखिए।", ans:"उपभोक्तावादी संस्कृति मनुष्य को अपव्ययी, असंतोषी और मानसिक रूप से दास बनाती है। यह पर्यावरण और सामाजिक मूल्यों दोनों को हानि पहुँचाती है।", type:"short"},
      {q:"पाठ के आधार पर 'सच्ची आवश्यकता' और 'कृत्रिम इच्छा' में अंतर स्पष्ट कीजिए।", ans:"सच्ची आवश्यकता जीवन-यापन के लिए अनिवार्य है, जबकि कृत्रिम इच्छा बाज़ार के प्रलोभन से उत्पन्न होती है। विवेक से दोनों में भेद करना आवश्यक है।", type:"short"},
      {q:"'काले मेघा पानी दे' शीर्षक की सार्थकता स्पष्ट कीजिए।", ans:"बच्चे सूखे के समय 'काले मेघा पानी दे' गाते हुए पानी माँगते थे; शीर्षक पाठ की केंद्रीय स्मृति और लोक-आस्था को व्यक्त करता है। अतः शीर्षक पूर्णतः सार्थक है।", type:"short"},
      {q:"धर्मवीर भारती का साहित्यिक परिचय दीजिए।", ans:"धर्मवीर भारती (1926–1997) प्रसिद्ध कवि, कथाकार और पत्रकार हैं; 'गुनाहों का देवता' और 'सूरज का सातवाँ घोड़ा' उनकी प्रमुख कृतियाँ हैं।", type:"short"},
      {q:"पाठ में वर्णित 'इंदर सेना' की गतिविधि लिखिए।", ans:"वर्षा न होने पर गाँव के बच्चे 'इंदर सेना' बनाकर घर-घर जाते और 'काले मेघा पानी दे' गाते हुए पानी माँगते थे। यह लोक-परंपरा सामूहिक भावना का प्रतीक थी।", type:"short"},
      {q:"'काले मेघा पानी दे' में लेखक की स्मृति-चेतना स्पष्ट कीजिए।", ans:"लेखक बचपन की इस स्मृति को भावुकता से याद करता है; यह स्मृति उसके मन में लोक-संस्कृति के प्रति गहन आस्था जगाती है। स्मृति यहाँ सांस्कृतिक चेतना का माध्यम है।", type:"short"},
      {q:"पाठ में प्रकृति के प्रति लोक-आस्था कैसे व्यक्त हुई है?", ans:"बच्चे मेघों से पानी की याचना गीतों के माध्यम से करते हैं; यह प्रकृति को चेतन मानने वाली लोक-आस्था है। मनुष्य और प्रकृति का यह आत्मीय संबंध भारतीय संस्कृति की विशेषता है।", type:"short"},
      {q:"धर्मवीर भारती की भाषा-शैली की विशेषता लिखिए।", ans:"भारती की भाषा सरल, प्रवाहमयी और भावप्रवण है; संस्मरणों में स्मृति और कल्पना का सुंदर मेल है। उनकी शैली पाठक को अतीत में ले जाती है।", type:"short"},
      {q:"'काले मेघा पानी दे' पाठ का सामाजिक महत्त्व लिखिए।", ans:"पाठ लोक-संस्कृति की सामूहिकता और एकता का दस्तावेज़ है; यह बताता है कि संकट के समय समाज एकजुट होकर प्रकृति से प्रार्थना करता था। यह सामाजिक सौहार्द का प्रतीक है।", type:"short"},
      {q:"लेखक के बचपन और वर्तमान के अंतर को पाठ के आधार पर स्पष्ट कीजिए।", ans:"बचपन में लोक-परंपराएँ जीवंत थीं और सामूहिकता थी; वर्तमान में वह आत्मीयता लुप्त होती जा रही है। लेखक इस परिवर्तन पर विषाद व्यक्त करता है।", type:"short"},
      {q:"'इंदर सेना' नामकरण का तात्पर्य स्पष्ट कीजिए।", ans:"इंद्र वर्षा के देवता हैं; बच्चों की टोली का 'इंदर सेना' नामकरण वर्षा के लिए देवता से याचना का भाव व्यक्त करता है। यह लोक-विश्वास का प्रतीक है।", type:"short"},
      {q:"पाठ में बाल-सुलभ उमंग का चित्रण स्पष्ट कीजिए।", ans:"गीत गाते, घर-घर जाते बच्चों में अपार उमंग है; सूखे की चिंता के बीच भी उनका उत्साह कम नहीं होता। यह बाल-मन की निश्छलता का सुंदर चित्र है।", type:"short"},
      {q:"लुट्टन पहलवान का चरित्र-चित्रण कीजिए।", ans:"लुट्टन गाँव का प्रसिद्ध पहलवान था; जवानी में उसने अखाड़े की शान बढ़ाई, परंतु बुढ़ापे में वह उपेक्षित हो गया। उसके चरित्र में खेल-भावना, स्वाभिमान और करुणा का समन्वय है।", type:"short"},
      {q:"फणीश्वरनाथ रेणु का साहित्यिक परिचय दीजिए।", ans:"फणीश्वरनाथ रेणु (1921–1977) हिंदी के प्रसिद्ध आंचलिक कथाकार हैं; 'मैला आँचल' (1954) उनकी कालजयी कृति है। उनकी रचनाओं में ग्रामीण बिहार का सजीव चित्रण है।", type:"short"},
      {q:"'पहलवान की ढोलक' में ढोलक का प्रतीकात्मक अर्थ स्पष्ट कीजिए।", ans:"ढोलक की थाप लुट्टन के जीवन की धड़कन है; उसके बंद होने से जीवन का सूनापन व्यक्त होता है। ढोलक लोककला और जीवन-उल्लास का प्रतीक है।", type:"short"},
      {q:"कहानी में बुढ़ापे की उपेक्षा का चित्रण स्पष्ट कीजिए।", ans:"जवानी में सम्मान पाने वाला लुट्टन बुढ़ापे में उपेक्षित हो जाता है; समाज उसकी सेवाओं को भूल जाता है। यह चित्रण मानवीय करुणा जगाता है।", type:"short"},
      {q:"रेणु की आंचलिकता की विशेषता लिखिए।", ans:"रेणु की भाषा में अंचल की बोली, लोकगीत और मुहावरों का प्रयोग है; पात्र और परिवेश पूर्णतः ग्रामीण हैं। उनकी आंचलिकता में यथार्थ और आत्मीयता का मेल है।", type:"short"},
      {q:"'पहलवान की ढोलक' शीर्षक की सार्थकता स्पष्ट कीजिए।", ans:"ढोलक कहानी का केंद्रीय प्रतीक है; लुट्टन के जीवन की धड़कन उसी में बसती है। शीर्षक कहानी के भाव को सटीक रूप से व्यक्त करता है।", type:"short"},
      {q:"कहानी में गुरु-शिष्य परंपरा का चित्रण स्पष्ट कीजिए।", ans:"अखाड़े में गुरु पहलवानों को न केवल कुश्ती, बल्कि जीवन-मूल्य भी सिखाता है; शिष्य गुरु के प्रति श्रद्धा रखते हैं। यह परंपरा ग्रामीण संस्कृति की धरोहर है।", type:"short"},
      {q:"लुट्टन के पुत्रों के प्रसंग का कहानी में क्या महत्त्व है?", ans:"दोनों पुत्रों की मृत्यु से लुट्टन टूट जाता है; यह प्रसंग उसके जीवन की त्रासदी को गहरा करता है। पुत्र-शोक में भी ढोलक की थाप उसका सहारा बनती है।", type:"short"},
      {q:"कहानी का मूल संदेश लिखिए।", ans:"कहानी का संदेश है कि लोककलाकारों और खेल-प्रतिभाओं का सम्मान जीवनभर होना चाहिए; बुढ़ापे में उनकी उपेक्षा समाज के लिए लज्जा है।", type:"short"},
      {q:"'पहलवान की ढोलक' में लोक-संस्कृति के तत्त्व लिखिए।", ans:"अखाड़ा, ढोलक की थाप, मेले का उल्लास और सामूहिक जीवन — ये सभी लोक-संस्कृति के तत्त्व कहानी में सजीव हैं। रेणु ने ग्रामीण उत्सव-धर्मिता को मार्मिकता से चित्रित किया है।", type:"short"},
      {q:"'शिरीष के फूल' निबंध में निहित जीवन-दर्शन स्पष्ट कीजिए।", ans:"शिरीष आँधी-तूफान में भी खिला रहता है; इससे लेखक ने विपत्तियों में भी जीवन-आस्था बनाए रखने का दर्शन निकाला है। धैर्य और सहनशीलता ही जीवन की शक्ति है।", type:"short"},
      {q:"हजारीप्रसाद द्विवेदी का साहित्यिक परिचय दीजिए।", ans:"हजारीप्रसाद द्विवेदी (1907–1979) प्रसिद्ध निबंधकार और आलोचक हैं; 'बाणभट्ट की आत्मकथा' उनकी प्रमुख कृति है। उनके निबंधों में भारतीय संस्कृति की गहन समझ है।", type:"short"},
      {q:"'शिरीष के फूल' शीर्षक की सार्थकता स्पष्ट कीजिए।", ans:"शिरीष का फूल निबंध का केंद्रीय प्रतीक है; उसी से लेखक ने जीवन-दर्शन की प्रेरणा ली है। शीर्षक निबंध के विषय और भाव दोनों को व्यक्त करता है।", type:"short"},
      {q:"निबंध में शिरीष और भारतीय संस्कृति की तुलना स्पष्ट कीजिए।", ans:"जैसे शिरीष प्रतिकूलता में भी खिला रहता है, वैसे ही भारतीय संस्कृति संकटों में भी अपनी जिजीविषा बनाए रखती है। यह तुलना सांस्कृतिक गौरव को व्यक्त करती है।", type:"short"},
      {q:"द्विवेदी जी की निबंध-कला की विशेषता लिखिए।", ans:"द्विवेदी जी के निबंधों में पांडित्य और लालित्य का समन्वय है; वे सामान्य विषय से भी गहन दार्शनिक अर्थ निकाल लेते हैं। उनकी भाषा प्रांजल और प्रभावशाली है।", type:"short"},
      {q:"शिरीष के फूल की विशेषताएँ लिखिए।", ans:"शिरीष का फूल ग्रीष्म में खिलता है; आँधी-तूफान में भी वह डाल पर टिका रहता है। उसकी यह दृढ़ता जीवन-संघर्ष की प्रेरणा है।", type:"short"},
      {q:"निबंध में 'जिजीविषा' का क्या तात्पर्य है?", ans:"'जिजीविषा' का अर्थ जीने की प्रबल इच्छा है; शिरीष के माध्यम से लेखक ने प्रतिकूल परिस्थितियों में भी जीने की इच्छा का महत्त्व बताया है।", type:"short"},
      {q:"'शिरीष के फूल' में प्रकृति और मानव-जीवन का संबंध स्पष्ट कीजिए।", ans:"लेखक प्रकृति के प्रतीकों से मानव-जीवन के सत्य उद्घाटित करता है; शिरीष का धैर्य मनुष्य के लिए आदर्श है। प्रकृति यहाँ जीवन-गुरु की भूमिका में है।", type:"short"},
      {q:"निबंध का समापन-भाव लिखिए।", ans:"निबंध का समापन आशावादी है; लेखक को विश्वास है कि भारतीय संस्कृति शिरीष की भाँति हर संकट में खिलती रहेगी। यह समापन पाठक में आस्था जगाता है।", type:"short"},
      {q:"द्विवेदी जी के निबंधों में सांस्कृतिक चेतना स्पष्ट कीजिए।", ans:"द्विवेदी जी के निबंधों में भारतीय संस्कृति के प्रति गहन निष्ठा और समन्वयवादी दृष्टि है। वे परंपरा और आधुनिकता का सेतु बनाते हैं।", type:"short"},
      {q:"आंबेडकर के अनुसार जाति-आधारित श्रम विभाजन क्यों अमानवीय है?", ans:"क्योंकि यह व्यक्ति की योग्यता और रुचि की उपेक्षा करके जन्म से पेशा तय करता है। इससे प्रतिभा का हनन होता है और मानवीय गरिमा को ठेस पहुँचती है।", type:"short"},
      {q:"डॉ. भीमराव आंबेडकर का जीवन-परिचय दीजिए।", ans:"डॉ. आंबेडकर (1891–1956) भारतीय संविधान के शिल्पी और समाज-सुधारक थे; 1956 में उन्होंने बौद्ध धर्म अपनाया। उन्हें 1990 में मरणोपरांत भारत रत्न मिला।", type:"short"},
      {q:"'श्रम विभाजन और जाति प्रथा' भाषण की पृष्ठभूमि लिखिए।", ans:"यह 1936 में जाति-उन्मूलन सम्मेलन के लिए तैयार भाषण था; इसमें आंबेडकर ने जाति प्रथा के उन्मूलन की माँग की। यह भाषण सामाजिक क्रांति का घोषणापत्र है।", type:"short"},
      {q:"आंबेडकर के अनुसार श्रम विभाजन का आदर्श रूप क्या है?", ans:"योग्यता और रुचि के आधार पर कार्य का बँटवारा ही आदर्श श्रम विभाजन है। इसमें व्यक्ति को अपनी क्षमता के अनुसार कार्य चुनने की स्वतंत्रता मिलती है।", type:"short"},
      {q:"जाति प्रथा आर्थिक विकास में कैसे बाधक है?", ans:"जाति प्रथा प्रतिभा को जन्म के बंधन में जकड़ती है; योग्य व्यक्ति को अवसर नहीं मिलता और अयोग्य को पद मिलता है। इससे समाज की उत्पादकता और विकास अवरुद्ध होता है।", type:"short"},
      {q:"आंबेडकर के सामाजिक न्याय संबंधी विचार लिखिए।", ans:"आंबेडकर समता, स्वतंत्रता और बंधुत्व के आदर्शों पर समाज की रचना चाहते थे। उनके अनुसार बिना सामाजिक न्याय के राजनीतिक स्वतंत्रता अधूरी है।", type:"short"},
      {q:"'एनिहिलेशन ऑफ कास्ट' का महत्त्व लिखिए।", ans:"यह कृति जाति प्रथा के उन्मूलन का तार्किक और नैतिक आधार प्रस्तुत करती है। इसने दलित-आंदोलन को वैचारिक दिशा दी।", type:"short"},
      {q:"पाठ में आंबेडकर की तर्क-शैली की विशेषता लिखिए।", ans:"आंबेडकर के तर्क तथ्यपरक, तार्किक और प्रामाणिक हैं; वे उदाहरणों से अपनी बात सिद्ध करते हैं। उनकी शैली में ओज और दृढ़ता है।", type:"short"},
      {q:"जाति प्रथा के उन्मूलन के उपाय लिखिए (आंबेडकर के अनुसार)।", ans:"आंबेडकर के अनुसार अंतरजातीय विवाह और योग्यता-आधारित व्यवस्था से जाति प्रथा का उन्मूलन संभव है। इसके लिए सामाजिक चेतना का जागरण आवश्यक है।", type:"short"},
      {q:"'श्रम विभाजन और जाति प्रथा' पाठ की प्रासंगिकता लिखिए।", ans:"आज भी जातिगत भेदभाव के अवशेष समाज में हैं; पाठ समता और योग्यता के आदर्शों की याद दिलाता है। यह नवपीढ़ी के लिए प्रेरणास्रोत है।", type:"short"},
      {q:"'सिल्वर वैडिंग' कहानी में पीढ़ी-अंतराल का चित्रण स्पष्ट कीजिए।", ans:"यशोधर बाबू पुराने मूल्यों के पक्षधर हैं, जबकि पुत्र भूषण आधुनिकता का प्रतिनिधि है; दोनों के विचारों में टकराव होता है। यह टकराव ही पीढ़ी-अंतराल का सजीव चित्र है।", type:"short"},
      {q:"मन्नू भंडारी का साहित्यिक परिचय दीजिए।", ans:"मन्नू भंडारी (1931–2021) प्रसिद्ध कथाकार हैं; 'आपका बंटी' उनकी कालजयी कृति है। उनकी कहानियों में मध्यवर्गीय जीवन का सूक्ष्म चित्रण है।", type:"short"},
      {q:"यशोधर बाबू के द्वंद्व का वर्णन कीजिए।", ans:"यशोधर बाबू अपने सिद्धांतों से समझौता नहीं करना चाहते, परंतु पुत्र के प्रेम के आगे झुकते हैं। यह द्वंद्व पुरानी पीढ़ी के अंतर्मन का सच्चा चित्र है।", type:"short"},
      {q:"'सिल्वर वैडिंग' शीर्षक की सार्थकता स्पष्ट कीजिए।", ans:"25वीं विवाह वर्षगाँठ (सिल्वर वैडिंग) के आयोजन के इर्द-गिर्द कहानी बुनी गई है; यही अवसर पीढ़ी-संघर्ष को उजागर करता है। शीर्षक कथानक के केंद्र को व्यक्त करता है।", type:"short"},
      {q:"भूषण का चरित्र-चित्रण कीजिए।", ans:"भूषण नई पीढ़ी का आधुनिक, स्वतंत्र विचारों वाला युवक है; वह पिता का सम्मान करता है परंतु अपने ढंग से जीना चाहता है। उसके चरित्र में आत्मविश्वास और संवेदनशीलता है।", type:"short"},
      {q:"कहानी में यशोधर बाबू की पत्नी की भूमिका लिखिए।", ans:"पत्नी पति और पुत्र के बीच सेतु का कार्य करती है; वह परंपरा का सम्मान करते हुए नई पीढ़ी की भावनाओं को भी समझती है। उसकी भूमिका संतुलनकारी है।", type:"short"},
      {q:"'सिल्वर वैडिंग' में मध्यवर्गीय जीवन का चित्रण स्पष्ट कीजिए।", ans:"कहानी में मध्यवर्गीय परिवार की आर्थिक मर्यादाएँ, सामाजिक प्रतिष्ठा की चिंता और मूल्य-संघर्ष सजीव हैं। यह चित्रण यथार्थपरक और मार्मिक है।", type:"short"},
      {q:"कहानी के अंत का भावार्थ लिखिए।", ans:"अंत में यशोधर बाबू नई वास्तविकता से समझौता करते हैं; यह समझौता पराजय नहीं, बल्कि स्नेह की विजय है। अंत आशावादी और मानवीय है।", type:"short"},
      {q:"मन्नू भंडारी की कहानी-कला की विशेषता लिखिए।", ans:"मन्नू भंडारी की कहानियों में मनोवैज्ञानिक सूक्ष्मता और सामाजिक यथार्थ का मेल है; भाषा सरल परंतु प्रभावशाली है। वे छोटे प्रसंगों से बड़े सत्य उद्घाटित करती हैं।", type:"short"},
      {q:"'सिल्वर वैडिंग' का सामाजिक संदेश लिखिए।", ans:"कहानी का संदेश है कि पीढ़ियों के बीच संवाद और समझ से अंतराल को पाटा जा सकता है। मूल्यों की रक्षा हठ से नहीं, स्नेह से होती है।", type:"short"},
      {q:"'जूझ' शीर्षक की सार्थकता स्पष्ट कीजिए।", ans:"लेखक का संपूर्ण जीवन गरीबी और उपेक्षा से जूझने की गाथा है; 'जूझ' अर्थात् निरंतर संघर्ष ही पाठ की आत्मा है। शीर्षक पूर्णतः सार्थक है।", type:"short"},
      {q:"आनंद यादव का जीवन-परिचय दीजिए।", ans:"आनंद यादव (जन्म 1935, महाराष्ट्र) प्रसिद्ध आत्मकथाकार हैं; 'जूझ' में उन्होंने अपने संघर्षपूर्ण जीवन का वर्णन किया है। उनकी रचना श्रम और शिक्षा के प्रति निष्ठा का दस्तावेज़ है।", type:"short"},
      {q:"'जूझ' पाठ में शिक्षा का महत्त्व स्पष्ट कीजिए।", ans:"लेखक के लिए शिक्षा गरीबी से मुक्ति का साधन थी; उसने खेत-मजदूरी के साथ पढ़ाई जारी रखी। पाठ शिक्षा को जीवन-परिवर्तन की शक्ति बताता है।", type:"short"},
      {q:"लेखक के पिता के चरित्र पर टिप्पणी कीजिए।", ans:"पिता कठोर और पढ़ाई के प्रति उदासीन थे; उनकी उपेक्षा ने लेखक के संघर्ष को और कठिन बनाया। फिर भी लेखक ने हार नहीं मानी।", type:"short"},
      {q:"'जूझ' पाठ का प्रेरक संदेश लिखिए।", ans:"पाठ का संदेश है कि दृढ़ संकल्प और परिश्रम से हर बाधा को पार किया जा सकता है। गरीबी शिक्षा की राह में बाधा नहीं बन सकती।", type:"short"},
      {q:"'जूझ' में गुरु-शिष्य संबंध की विशेषता लिखिए।", ans:"गुरु ने निर्धन छात्र की प्रतिभा पहचानकर निःशुल्क पढ़ाया और उसका मनोबल बढ़ाया। यह संबंध ज्ञान के प्रति निष्ठा और मानवीय स्नेह का आदर्श है।", type:"short"},
      {q:"लेखक की लगनशीलता के उदाहरण दीजिए।", ans:"खेत-मजदूरी के बाद थके होने पर भी लेखक पढ़ाई करता था; अभावों में भी उसने विद्यालय नहीं छोड़ा। यह लगन उसके चरित्र की पहचान है।", type:"short"},
      {q:"'जूझ' पाठ में ग्रामीण जीवन का चित्रण स्पष्ट कीजिए।", ans:"पाठ में गाँव की गरीबी, खेत-मजदूरी और पाठशाला का सजीव चित्रण है। ग्रामीण जीवन की कठिनाइयों के बीच शिक्षा की लौ जलती दिखती है।", type:"short"},
      {q:"आत्मकथा के रूप में 'जूझ' की विशेषता लिखिए।", ans:"'जूझ' में लेखक ने अपने जीवन का ईमानदार और निश्छल वर्णन किया है; आत्मप्रशंसा के बजाय संघर्ष की सच्चाई है। यह आत्मकथा प्रेरणादायी दस्तावेज़ है।", type:"short"},
      {q:"'जूझ' पाठ से विद्यार्थियों को क्या प्रेरणा मिलती है?", ans:"विद्यार्थियों को सीख मिलती है कि अभावों से घबराकर पढ़ाई नहीं छोड़नी चाहिए; परिश्रम और लगन से सफलता अवश्य मिलती है।", type:"short"},
      {q:"'मुअनजो-दड़ो' नाम का तात्पर्य स्पष्ट कीजिए।", ans:"'मुअनजो-दड़ो' का अर्थ 'मुर्दों का टीला' है; यह नाम उस प्राचीन नगर के खंडहरों को देखकर पड़ा। नाम में ही इतिहास की गहराई छिपी है।", type:"short"},
      {q:"ओम थानवी का परिचय दीजिए।", ans:"ओम थानवी (जन्म 1957, राजस्थान) प्रसिद्ध पत्रकार और 'जनसत्ता' के पूर्व संपादक हैं। 'अतीत में दबे पाँव' उनका प्रसिद्ध यात्रा-वृत्तांत है।", type:"short"},
      {q:"मुअनजो-दड़ो के विशाल स्नानागार का वर्णन कीजिए।", ans:"विशाल स्नानागार पक्की ईंटों से बना जलाशय था; इसमें उतरने के लिए सीढ़ियाँ बनी थीं। यह सार्वजनिक जीवन और तकनीकी कुशलता का प्रमाण है।", type:"short"},
      {q:"सिंधु घाटी सभ्यता की जल-निकासी व्यवस्था पर टिप्पणी कीजिए।", ans:"घरों से गंदा पानी निकालने के लिए पक्की नालियाँ बनी थीं; यह व्यवस्था अत्यंत उन्नत थी। यह प्राचीन भारतीयों की वैज्ञानिक चेतना को दर्शाती है।", type:"short"},
      {q:"मुअनजो-दड़ो की खोज का ऐतिहासिक महत्त्व लिखिए।", ans:"1922 में राखालदास बनर्जी द्वारा खोज से भारत की पाँच हजार वर्ष पुरानी नगरीय सभ्यता का पता चला। इसने भारतीय इतिहास की प्राचीनता सिद्ध की।", type:"short"},
      {q:"'अतीत में दबे पाँव' में लेखक की अनुभूति स्पष्ट कीजिए।", ans:"प्राचीन अवशेषों को देखकर लेखक गर्व और विषाद दोनों अनुभव करता है; गर्व सभ्यता की उन्नति पर और विषाद उसके पतन पर। यह अनुभूति पाठ को भावप्रवण बनाती है।", type:"short"},
      {q:"सिंधु घाटी सभ्यता के नगर-नियोजन की विशेषताएँ लिखिए।", ans:"सड़कें सीधी और नियोजित थीं; मकान पक्की ईंटों के बने थे। नगर दो भागों में बँटा था, जो उन्नत प्रशासन का प्रमाण है।", type:"short"},
      {q:"पुरातात्त्विक धरोहरों के संरक्षण का संदेश लिखिए।", ans:"पाठ का संदेश है कि प्राचीन धरोहरें हमारी सांस्कृतिक पहचान हैं; इनका संरक्षण वर्तमान पीढ़ी का कर्तव्य है। उपेक्षा से इतिहास लुप्त हो जाएगा।", type:"short"},
      {q:"यात्रा-वृत्तांत के रूप में पाठ की विशेषता लिखिए।", ans:"लेखक ने प्रत्यक्ष दर्शन के आधार पर वर्णन किया है; तथ्यों के साथ भावनाओं का भी समावेश है। यह शैली पाठ को जीवंत और विश्वसनीय बनाती है।", type:"short"},
      {q:"मुअनजो-दड़ो से प्राप्त मुहरों का महत्त्व लिखिए।", ans:"मुहरों पर अंकित चित्र और लिपि उस समय की व्यापारिक और सांस्कृतिक गतिविधियों की जानकारी देती हैं। ये मुहरें सभ्यता के अध्ययन का प्रमुख स्रोत हैं।", type:"short"},
      {q:"जनसंचार के प्रमुख कार्यों का वर्णन कीजिए।", ans:"जनसंचार के प्रमुख कार्य सूचना देना, शिक्षा प्रदान करना और मनोरंजन करना हैं। इसके माध्यम से जनमत का निर्माण और सामाजिक चेतना का विकास होता है।", type:"short"},
      {q:"पत्रकारिता में सत्यता का महत्त्व स्पष्ट कीजिए।", ans:"सत्यता पत्रकारिता की आत्मा है; तथ्यपरक समाचार ही पाठक का विश्वास जीतता है। असत्य समाचार से पत्रकारिता की विश्वसनीयता नष्ट होती है।", type:"short"},
      {q:"संपादकीय लेखन की विशेषताएँ लिखिए।", ans:"संपादकीय में समसामयिक विषय पर पत्र की नीति और मत व्यक्त होता है; भाषा संयमित और तर्कसंगत होती है। यह जनमत को दिशा देने का कार्य करता है।", type:"short"},
      {q:"साक्षात्कार की तैयारी कैसे करनी चाहिए?", ans:"साक्षात्कार से पूर्व विषय और व्यक्तित्व का अध्ययन आवश्यक है; प्रश्न क्रमबद्ध और सटीक होने चाहिए। अच्छी तैयारी से साक्षात्कार सार्थक बनता है।", type:"short"},
      {q:"अनुच्छेद और निबंध में अंतर स्पष्ट कीजिए।", ans:"अनुच्छेद में एक ही भाव का संक्षिप्त विस्तार होता है, जबकि निबंध में विषय का विस्तृत विवेचन होता है। अनुच्छेद निबंध का एक अंग भी हो सकता है।", type:"short"},
      {q:"निबंध-लेखन के अंगों का वर्णन कीजिए।", ans:"निबंध के तीन अंग हैं — प्रस्तावना, विषय-विस्तार और उपसंहार। प्रस्तावना में विषय का परिचय, विस्तार में विवेचन और उपसंहार में निष्कर्ष होता है।", type:"short"},
      {q:"जनसंचार माध्यमों के प्रकार लिखिए।", ans:"जनसंचार के प्रमुख माध्यम हैं — समाचार-पत्र (प्रिंट), रेडियो-दूरदर्शन (इलेक्ट्रॉनिक) और इंटरनेट (डिजिटल)। प्रत्येक माध्यम की अपनी विशेषता और पहुँच है।", type:"short"},
      {q:"संपादक के गुणों का वर्णन कीजिए।", ans:"संपादक में निष्पक्षता, भाषायी दक्षता और समसामयिक ज्ञान आवश्यक है। उसमें तथ्यों की परख और जनहित की भावना होनी चाहिए।", type:"short"},
      {q:"विज्ञापन और समाचार में अंतर स्पष्ट कीजिए।", ans:"समाचार तथ्यपरक सूचना है, जबकि विज्ञापन किसी वस्तु या सेवा का प्रचार है। समाचार का उद्देश्य जानकारी देना और विज्ञापन का उद्देश्य विक्रय बढ़ाना है।", type:"short"},
      {q:"सृजनात्मक लेखन का महत्त्व लिखिए।", ans:"सृजनात्मक लेखन से कल्पना-शक्ति और अभिव्यक्ति-कौशल का विकास होता है। यह व्यक्तित्व को निखारता और साहित्यिक रुचि को बढ़ाता है।", type:"short"},
      {q:"'कविता के बहाने' में कवि ने कविता की सामाजिक भूमिका कैसे बताई है?", ans:"कवि के अनुसार कविता मनुष्य को आत्मचिंतन के लिए प्रेरित करती है और समाज में मानवीय संवेदना का प्रसार करती है। यही उसकी सामाजिक भूमिका है।", type:"short"},
      {q:"कुँवर नारायण की भाषा-शैली की विशेषता लिखिए।", ans:"उनकी भाषा संयमित, सटीक और चिंतनप्रधान है; बिंब सादे परंतु अर्थगर्भित होते हैं। शैली में दार्शनिक गहराई है।", type:"short"},
      {q:"'कविता के बहाने' कविता का संदेश लिखिए।", ans:"संदेश है कि कविता को जीवन से जुड़ना चाहिए; कोरी शाब्दिक कला के बजाय मानवीय अनुभूति ही सच्ची कविता है।", type:"short"},
      {q:"कवि ने 'बहाने' शब्द का प्रयोग क्यों किया है?", ans:"'बहाने' से तात्पर्य है कि कविता के माध्यम से कवि ने कविता के स्वरूप पर ही विचार किया है। यह आत्मचिंतनपरक प्रयोग है।", type:"short"},
      {q:"कुँवर नारायण और मुक्तिबोध की काव्य-दृष्टि में अंतर लिखिए।", ans:"मुक्तिबोध की दृष्टि संघर्षशील और विद्रोही है, जबकि कुँवर नारायण की चिंतनशील और संयमित है। दोनों समकालीन कविता के सशक्त स्वर हैं।", type:"short"},
      {q:"दीर्घ संधि की परिभाषा सोदाहरण लिखिए।", ans:"ह्रस्व या दीर्घ अ, इ, उ के बाद समान स्वर आने पर दोनों मिलकर दीर्घ स्वर हो जाते हैं; जैसे — विद्या + आलय = विद्यालय।", type:"short"},
      {q:"गुण संधि का नियम सोदाहरण लिखिए।", ans:"अ/आ के बाद इ/ई आने पर 'ए', उ/ऊ आने पर 'ओ' और ऋ आने पर 'अर्' हो जाता है; जैसे — देव + इंद्र = देवेंद्र।", type:"short"},
      {q:"यण संधि का नियम सोदाहरण लिखिए।", ans:"इ/ई, उ/ऊ, ऋ के बाद भिन्न स्वर आने पर क्रमशः य्, व्, र् हो जाता है; जैसे — इति + आदि = इत्यादि।", type:"short"},
      {q:"द्विगु समास की परिभाषा सोदाहरण लिखिए।", ans:"जिस समास में पूर्व पद संख्यावाची हो, उसे द्विगु समास कहते हैं; जैसे — चौराहा (चार राहों का समूह)।", type:"short"},
      {q:"अव्ययीभाव समास की परिभाषा सोदाहरण लिखिए।", ans:"जिस समास में पूर्व पद अव्यय हो और प्रधान हो, उसे अव्ययीभाव समास कहते हैं; जैसे — यथाशक्ति (शक्ति के अनुसार)।", type:"short"},
      {q:"कर्मधारय समास की परिभाषा सोदाहरण लिखिए।", ans:"जिस समास में विशेषण-विशेष्य या उपमान-उपमेय का मेल हो, उसे कर्मधारय समास कहते हैं; जैसे — नीलकमल (नीला है कमल)।", type:"short"},
      {q:"द्वंद्व समास की परिभाषा सोदाहरण लिखिए।", ans:"जिस समास में दोनों पद प्रधान हों और 'और' से जुड़े हों, उसे द्वंद्व समास कहते हैं; जैसे — माता-पिता।", type:"short"},
      {q:"'पर्यायवाची' शब्द से क्या तात्पर्य है? दो उदाहरण दीजिए।", ans:"समान अर्थ वाले शब्द पर्यायवाची कहलाते हैं; जैसे — सूर्य : दिवाकर, भानु; अग्नि : पावक, अनल।", type:"short"},
      {q:"'विलोम' शब्द से क्या तात्पर्य है? दो उदाहरण दीजिए।", ans:"विपरीत अर्थ वाले शब्द विलोम कहलाते हैं; जैसे — सुख-दुःख, आदि-अंत।", type:"short"},
      {q:"मुहावरे की परिभाषा दो उदाहरण सहित लिखिए।", ans:"लाक्षणिक अर्थ वाला वाक्यांश मुहावरा कहलाता है; जैसे — 'आँखों का तारा' (बहुत प्यारा), 'नाक में दम करना' (बहुत परेशान करना)।", type:"short"},
      {q:"'अनेक शब्दों के लिए एक शब्द' से क्या तात्पर्य है? दो उदाहरण दीजिए।", ans:"अनेक शब्दों के भाव को एक शब्द में व्यक्त करना; जैसे — 'जो कभी बूढ़ा न हो' : अजर, 'जिसका कोई शत्रु न हो' : अजातशत्रु।", type:"short"},
      {q:"वृद्धि संधि का नियम सोदाहरण लिखिए।", ans:"अ/आ के बाद ए/ऐ आने पर 'ऐ' और ओ/औ आने पर 'औ' हो जाता है; जैसे — महा + औषधि = महौषधि।", type:"short"},
      {q:"अयादि संधि का नियम सोदाहरण लिखिए।", ans:"ए, ऐ, ओ, औ के बाद भिन्न स्वर आने पर क्रमशः अय्, आय्, अव्, आव् हो जाता है; जैसे — ने + अन = नयन।", type:"short"},
      {q:"तत्पुरुष समास की परिभाषा सोदाहरण लिखिए।", ans:"जिस समास में उत्तर पद प्रधान हो, उसे तत्पुरुष समास कहते हैं; जैसे — गंगाजल (गंगा का जल)।", type:"short"},
      {q:"बहुव्रीहि समास की परिभाषा सोदाहरण लिखिए।", ans:"जिस समास में दोनों पद गौण होकर किसी तीसरे पद का बोध कराएँ, उसे बहुव्रीहि समास कहते हैं; जैसे — दशानन (दस हैं आनन जिसके, अर्थात् रावण)।", type:"short"},
      {q:"'आँखें दिखाना' और 'आँखों का तारा' मुहावरों का अर्थ लिखिए।", ans:"'आँखें दिखाना' का अर्थ क्रोध करना और 'आँखों का तारा' का अर्थ बहुत प्यारा है।", type:"short"},
      {q:"'सूर्य' और 'चंद्रमा' के दो-दो पर्यायवाची लिखिए।", ans:"सूर्य : दिवाकर, भानु; चंद्रमा : सुधाकर, निशाकर।", type:"short"},
      {q:"'जय-पराजय' और 'धर्म-अधर्म' में विलोम संबंध स्पष्ट कीजिए।", ans:"'जय' का विलोम 'पराजय' और 'धर्म' का विलोम 'अधर्म' है; ये परस्पर विपरीत अर्थ देते हैं।", type:"short"},
      {q:"संधि और समास में अंतर स्पष्ट कीजिए।", ans:"संधि वर्णों के मेल का विकार है (जैसे — विद्यालय), जबकि समास शब्दों के मेल का संक्षिप्त रूप है (जैसे — राजपुत्र)। संधि ध्वनि-स्तर पर और समास शब्द-स्तर पर होती है।", type:"short"},
      {q:"'लोहे के चने चबाना' मुहावरे का वाक्य में प्रयोग कीजिए।", ans:"आई.ए.एस. की परीक्षा उत्तीर्ण करना लोहे के चने चबाने के समान है।", type:"short"}
